// 24-S3 acceptance: the snapshot saves are gone (EPIC, "Retiring snapshot
// saves"). The actions module exports none of them, nothing in the app calls
// them, the editor saves through the commit path and publishes through
// publishAtVersion, and the editor's loader gives the version and epoch its
// confirmed state starts from. Do not edit this file to match an
// implementation.
import { readdirSync, readFileSync, statSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { createBlankPuzzle, serializePuzzle } from '@/lib/puzzle-storage';

const mocks = vi.hoisted(() => ({ requireSession: vi.fn(), findUnique: vi.fn() }));
vi.mock('@/lib/require-session', () => ({ requireSession: mocks.requireSession }));
vi.mock('next/cache', () => ({ revalidatePath: vi.fn() }));
vi.mock('@/lib/prisma', () => ({ prisma: { puzzle: { findUnique: mocks.findUnique } } }));

import * as actions from './actions';

const REMOVED = ['saveGrid', 'saveHints', 'saveTitle', 'enterHints', 'publishPuzzle', 'flushPendingSaves', 'SNAPSHOT_FENCE', 'updateUnlessPublished'];
const SRC = fileURLToPath(new URL('../../', import.meta.url));

function files(dir: string): string[] {
  return readdirSync(dir).flatMap((name) => {
    const path = join(dir, name);
    if (statSync(path).isDirectory()) return files(path);
    return /\.(ts|tsx)$/.test(name) && !/\.test\.tsx?$/.test(name) ? [path] : [];
  });
}
const withoutComments = (code: string) => code.replace(/\/\*[\s\S]*?\*\//g, '').replace(/(^|[^:])\/\/.*$/gm, '$1');

beforeEach(() => {
  vi.resetAllMocks();
  mocks.requireSession.mockResolvedValue({ user: { id: 'adam' } });
});

describe('24-S3-11 snapshot saves removed', () => {
  it('the actions module exports none of the snapshot actions', () => {
    for (const name of REMOVED) expect(Object.keys(actions), name).not.toContain(name);
    expect(typeof actions.commitOperation).toBe('function');
    expect(typeof actions.publishAtVersion).toBe('function');
  });

  it('no application source refers to them', () => {
    const offenders = files(SRC).flatMap((path) => {
      // The operation kind 'enterHints' is a string; the removed action was an identifier.
      const code = withoutComments(readFileSync(path, 'utf8')).replace(/(['"])(?:\\.|(?!\1).)*\1/g, '""');
      return REMOVED.filter((name) => new RegExp(`\\b${name}\\b`).test(code)).map((name) => `${path}: ${name}`);
    });
    expect(offenders).toEqual([]);
  });

  it('the editor commits operations and publishes at a version', () => {
    const editor = withoutComments(['components/grid/PuzzleGridEditor.tsx', 'components/grid/editor-saver.ts']
      .map((path) => readFileSync(join(SRC, path), 'utf8')).join('\n'));
    expect(editor).toMatch(/\bcommitOperation\(/);
    expect(editor).toMatch(/\bpublishAtVersion\(/);
    expect(editor).toMatch(/keepalive:\s*true/);
    expect(editor).toMatch(/\/api\/puzzles\/\$\{[^}]+\}\/operations/);
    expect(editor).toMatch(/beforeunload/);
  });

  it('the loader gives the version and reset epoch', async () => {
    const stored = serializePuzzle(createBlankPuzzle('mini'));
    mocks.findUnique.mockResolvedValue({
      ...stored, id: 'p', builderId: 'adam', title: 'T', publishedAt: null, visibility: 'private', version: 7, resetEpoch: 2,
    });
    expect(await actions.loadPuzzle('p')).toMatchObject({ id: 'p', version: 7, resetEpoch: 2 });
  });
});
